// Apply saved theme immediately (before DOM renders to prevent flash)
(function () {
  var saved = localStorage.getItem("theme") || "light";
  document.documentElement.setAttribute("data-bs-theme", saved);
})();

// Auto-inject sidebar when this script loads
(function () {
  "use strict";

  function loadSidebar() {
    const sidebarContainer = document.getElementById("sidebar-container");

    if (!sidebarContainer) {
      console.error(
        'Sidebar container not found. Please add <div id="sidebar-container"></div> to your page.',
      );
      return;
    }

    // Insert the sidebar HTML
    sidebarContainer.innerHTML = SIDEBAR_HTML;

    // Update theme toggle to reflect current theme state
    var currentTheme =
      document.documentElement.getAttribute("data-bs-theme") || "light";
    var themeIcon = document.getElementById("theme-icon");
    var themeLabel = document.getElementById("theme-label");
    if (themeIcon)
      themeIcon.className =
        currentTheme === "dark" ? "bx bxs-sun" : "bx bxs-moon";
    if (themeLabel)
      themeLabel.textContent =
        currentTheme === "dark" ? "Light Mode" : "Dark Mode";

    // Highlight the current page in the nav: match each link's filename to the
    // current URL, mark its <li> .active, and open any ancestor sub-menus.
    try {
      var current = (location.pathname.split("/").pop() || "home.htm").toLowerCase();
      var navLinks = sidebarContainer.querySelectorAll(".menu a[href]");
      navLinks.forEach(function (a) {
        var href = a.getAttribute("href");
        if (!href || href === "#") return;
        var file = href.split("/").pop().split("?")[0].toLowerCase();
        if (!file || file !== current) return;
        var li = a.closest(".menu-item");
        if (li) li.classList.add("active");
        // Open every ancestor sub-menu so the active item is visible.
        var node = li ? li.parentElement : null;
        while (node && node !== sidebarContainer) {
          if (
            node.classList &&
            node.classList.contains("menu-item") &&
            node.classList.contains("sub-menu")
          ) {
            node.classList.add("open");
          }
          node = node.parentElement;
        }
      });
    } catch (e) {
      console.warn("Sidebar active-page highlight failed", e);
    }

    // Wait for next frame to ensure DOM is ready, then load sidebar-sidebar.js
    requestAnimationFrame(() => {
      const script = document.createElement("script");
      script.src = "js/project/2.0/sidebar.js";
      script.onload = function () {
        console.log("Sidebar loaded and initialized successfully");
      };
      script.onerror = function () {
        console.error("Failed to load sidebar functionality script");
      };
      document.body.appendChild(script);
    });
  }

  // Load sidebar when DOM is ready
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", loadSidebar);
  } else {
    loadSidebar();
  }
})();
